package com.cpf.starter.webhook;import java.net.http.HttpClient;import java.time.Duration;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Bean;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;@AutoConfiguration @ConditionalOnProperty(prefix="cpf.integration.webhook",name="enabled",havingValue="true") public class CpfWebhookAutoConfiguration {@Bean CpfWebhookClient cpfWebhookClient(JdbcTemplate jdbc,Environment e){String secret=e.getRequiredProperty("cpf.integration.webhook.signing-secret");if(secret.length()<32)throw new IllegalStateException("webhook signing secret must be 32+ chars");return new CpfWebhookClient(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build(),jdbc,secret,Duration.ofSeconds(e.getProperty("cpf.integration.webhook.timeout-seconds",Integer.class,10)));}}
